<?php
declare(strict_types=1);
session_start();
$root=dirname(__DIR__,3);$cfg=require $root.'/config.php';date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');
if(empty($_SESSION['user'])){header('Location:index.php');exit;}
$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
require_once $root.'/app/Core/UnifiedSidebar.php';
function se($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sManage():bool{if(($_SESSION['user']['role']??'')==='admin')return true;$p=$_SESSION['user']['permissions']??[];return !empty($p['technical_projects']['manage']);}
function sView():bool{if(($_SESSION['user']['role']??'')==='admin')return true;$p=$_SESSION['user']['permissions']??[];return !empty($p['technical_projects']['view'])||!empty($p['technical_projects']['manage']);}
if(!sView()){http_response_code(403);exit('No tenés permiso para ver la planificación técnica.');}
$a=$_GET['a']??'technical_schedule';
if($a==='save_schedule_event'){
 if(!sManage()){http_response_code(403);exit('No tenés permiso para gestionar la planificación técnica.');}
 $id=(int)($_POST['event_id']??0);$project=(int)($_POST['project_id']??0);$date=$_POST['work_date']??'';$title=trim($_POST['title']??'')?:'Trabajo en obra';$start=$_POST['start_time']??'';$end=$_POST['end_time']??'';$notes=trim($_POST['notes']??'');$status=$_POST['status']??'planificado';$users=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['users']??[])))));
 if(!$project||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!in_array($status,['planificado','realizado','cancelado'],true))exit('Datos inválidos.');
 $db->beginTransaction();try{
  if($id){$db->prepare('UPDATE technical_schedule_events SET project_id=?,work_date=?,start_time=?,end_time=?,title=?,notes=?,status=? WHERE id=?')->execute([$project,$date,$start?:null,$end?:null,$title,$notes,$status,$id]);$db->prepare('DELETE FROM technical_schedule_users WHERE event_id=?')->execute([$id]);}
  else{$db->prepare('INSERT INTO technical_schedule_events(project_id,work_date,start_time,end_time,title,notes,status,created_by_user_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$project,$date,$start?:null,$end?:null,$title,$notes,$status,(int)($_SESSION['user']['id']??0)?:null]);$id=(int)$db->lastInsertId();}
  $ins=$db->prepare('INSERT INTO technical_schedule_users(event_id,user_id) VALUES(?,?)');foreach($users as $uid)$ins->execute([$id,$uid]);$db->commit();$_SESSION['msg']='Planificación guardada.';
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
 header('Location:?a=technical_schedule&month='.substr($date,0,7));exit;
}
$month=$_GET['month']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');$first=new DateTimeImmutable($month.'-01');$last=$first->modify('last day of this month');$gridStart=$first->modify('monday this week');$gridEnd=$last->modify('sunday this week');$prev=$first->modify('-1 month')->format('Y-m');$next=$first->modify('+1 month')->format('Y-m');
$filterProject=(int)($_GET['project_id']??0);$filterUser=(int)($_GET['user_id']??0);
$projects=$db->query("SELECT p.id,p.project_number,p.name FROM projects p ORDER BY p.project_number DESC,p.name")->fetchAll();
$techUsers=$db->query("SELECT DISTINCT u.id,u.name,up.area FROM users u LEFT JOIN user_profiles up ON up.id=u.profile_id WHERE u.active=1 AND (up.area='tecnico' OR u.role='admin' OR EXISTS(SELECT 1 FROM project_technical_users ptu WHERE ptu.user_id=u.id) OR EXISTS(SELECT 1 FROM projects p2 WHERE p2.technical_manager_user_id=u.id)) ORDER BY u.name")->fetchAll();
$where=['e.work_date BETWEEN ? AND ?'];$args=[$gridStart->format('Y-m-d'),$gridEnd->format('Y-m-d')];if($filterProject){$where[]='e.project_id=?';$args[]=$filterProject;}if($filterUser){$where[]='EXISTS(SELECT 1 FROM technical_schedule_users fsu WHERE fsu.event_id=e.id AND fsu.user_id=?)';$args[]=$filterUser;}if(!sManage()){$uid=(int)($_SESSION['user']['id']??0);$where[]='EXISTS(SELECT 1 FROM technical_schedule_users own WHERE own.event_id=e.id AND own.user_id=?)';$args[]=$uid;}
$sql="SELECT e.*,p.project_number,p.name project_name,GROUP_CONCAT(DISTINCT u.name ORDER BY u.name SEPARATOR ', ') user_names FROM technical_schedule_events e JOIN projects p ON p.id=e.project_id LEFT JOIN technical_schedule_users su ON su.event_id=e.id LEFT JOIN users u ON u.id=su.user_id WHERE ".implode(' AND ',$where)." GROUP BY e.id ORDER BY e.work_date,e.start_time,e.id";$s=$db->prepare($sql);$s->execute($args);$events=$s->fetchAll();$byDate=[];foreach($events as $ev)$byDate[$ev['work_date']][]=$ev;
$edit=null;$editUsers=[];if(sManage()&&!empty($_GET['event_id'])){$eid=(int)$_GET['event_id'];$s=$db->prepare('SELECT * FROM technical_schedule_events WHERE id=?');$s->execute([$eid]);$edit=$s->fetch();if($edit){$s=$db->prepare('SELECT user_id FROM technical_schedule_users WHERE event_id=?');$s->execute([$eid]);$editUsers=array_map('intval',array_column($s->fetchAll(),'user_id'));}}
$formDate=$_GET['date']??($edit['work_date']??date('Y-m-d'));$msg=$_SESSION['msg']??null;unset($_SESSION['msg']);$monthNames=[1=>'enero',2=>'febrero',3=>'marzo',4=>'abril',5=>'mayo',6=>'junio',7=>'julio',8=>'agosto',9=>'septiembre',10=>'octubre',11=>'noviembre',12=>'diciembre'];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Planificación técnica · Punto ERP</title><style><?=erpSidebarCss()?>body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.4 system-ui}.main{margin-left:var(--sidebar);padding:28px 3%}.top{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.top h1{flex:1}.btn{display:inline-block;border:0;border-radius:8px;padding:9px 13px;background:var(--o);color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.btn.light{background:#edf0f3;color:var(--ink)}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px;margin-bottom:18px}.filters{display:grid;grid-template-columns:1fr 1fr auto;gap:10px}.filters select,.filters button,input,select,textarea{width:100%;padding:10px;border:1px solid #cbd1d7;border-radius:8px;font:inherit}.calendar{display:grid;grid-template-columns:repeat(7,minmax(150px,1fr));border:1px solid var(--line);border-radius:12px;overflow:hidden;background:#fff}.dow{padding:10px;background:#f1f3f5;font-weight:800;text-align:center}.day{min-height:150px;padding:8px;border-top:1px solid var(--line);border-right:1px solid var(--line);background:#fff}.day:nth-child(7n){border-right:0}.day.other{background:#fafafa;color:#a2a7ad}.day.today{box-shadow:inset 0 0 0 2px var(--o)}.day-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}.day-num{font-weight:800}.add{font-size:18px;text-decoration:none;color:var(--o)}.event{display:block;margin:6px 0;padding:7px 8px;border-radius:8px;background:#fff3e9;border-left:4px solid var(--o);color:var(--ink);text-decoration:none;font-size:12px}.event.done{background:#eef8f3;border-left-color:#19835f}.event.cancel{opacity:.55;text-decoration:line-through}.event b{display:block;font-size:12px}.muted{color:var(--muted)}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.full{grid-column:1/-1}.checks{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.check{border:1px solid var(--line);border-radius:8px;padding:8px}.flash{padding:11px 14px;background:#eefaf5;border:1px solid #bfe8d4;border-radius:8px;margin-bottom:15px}@media(max-width:1100px){.calendar{overflow:auto;grid-template-columns:repeat(7,minmax(135px,1fr))}}@media(max-width:900px){.main{margin-left:0;padding:18px 12px}.filters,.form-grid{grid-template-columns:1fr}.calendar{display:block}.dow{display:none}.day{min-height:auto;border-right:0}.checks{grid-template-columns:1fr}}</style></head><body><?php erpSidebar('technical_schedule');?><main class="main"><?php if($msg):?><div class="flash"><?=se($msg)?></div><?php endif;?><div class="top"><h1>Planificación técnica</h1><a class="btn light" href="?a=technical_schedule&month=<?=$prev?>">← Mes anterior</a><a class="btn light" href="?a=technical_schedule&month=<?=date('Y-m')?>">Hoy</a><a class="btn light" href="?a=technical_schedule&month=<?=$next?>">Mes siguiente →</a></div><p class="muted">Agenda mensual de obras y técnicos · <?=ucfirst($monthNames[(int)$first->format('n')])?> <?=$first->format('Y')?></p><form class="card filters" method="get"><input type="hidden" name="a" value="technical_schedule"><input type="hidden" name="month" value="<?=se($month)?>"><select name="project_id"><option value="">Todos los proyectos</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>" <?=$filterProject===$p['id']?'selected':''?>><?=se($p['project_number'].' · '.$p['name'])?></option><?php endforeach;?></select><select name="user_id"><option value="">Todos los técnicos</option><?php foreach($techUsers as $u):?><option value="<?=$u['id']?>" <?=$filterUser===$u['id']?'selected':''?>><?=se($u['name'])?></option><?php endforeach;?></select><button class="btn" type="submit">Filtrar</button></form>
<div class="calendar"><?php foreach(['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'] as $d):?><div class="dow"><?=$d?></div><?php endforeach;?><?php for($d=$gridStart;$d<=$gridEnd;$d=$d->modify('+1 day')):$date=$d->format('Y-m-d');$other=$d->format('m')!==$first->format('m');?><div class="day <?=$other?'other':''?> <?=$date===date('Y-m-d')?'today':''?>"><div class="day-head"><span class="day-num"><?=$d->format('j')?></span><?php if(sManage()):?><a class="add" href="?a=technical_schedule&month=<?=$month?>&date=<?=$date?>#form">＋</a><?php endif;?></div><?php foreach($byDate[$date]??[] as $ev):$cls=$ev['status']==='realizado'?'done':($ev['status']==='cancelado'?'cancel':'');$eventHref=sManage()?('?a=technical_schedule&month='.$month.'&event_id='.$ev['id'].'#form'):('?a=daily_report&event_id='.$ev['id']);?><a class="event <?=$cls?>" href="<?=se($eventHref)?>"><b><?=se($ev['project_number'].' · '.$ev['project_name'])?></b><?=se($ev['start_time']?substr($ev['start_time'],0,5):'')?><?=($ev['start_time']&&$ev['end_time'])?'–'.se(substr($ev['end_time'],0,5)):''?><br><?=se($ev['title'])?><br><span class="muted"><?=se($ev['user_names']?:'Sin técnicos asignados')?></span></a><?php endforeach;?></div><?php endfor;?></div>
<?php if(sManage()):?><section class="card" id="form"><h2><?=$edit?'Editar planificación':'Nueva planificación'?></h2><form method="post" action="?a=save_schedule_event"><input type="hidden" name="event_id" value="<?=se($edit['id']??'')?>"><div class="form-grid"><div><label>Proyecto</label><select name="project_id" required><option value="">Seleccionar…</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>" <?=((int)($edit['project_id']??0)===(int)$p['id'])?'selected':''?>><?=se($p['project_number'].' · '.$p['name'])?></option><?php endforeach;?></select></div><div><label>Fecha</label><input type="date" name="work_date" value="<?=se($edit['work_date']??$formDate)?>" required></div><div><label>Desde</label><input type="time" name="start_time" value="<?=se(isset($edit['start_time'])&&$edit['start_time']?substr($edit['start_time'],0,5):'08:00')?>"></div><div><label>Hasta</label><input type="time" name="end_time" value="<?=se(isset($edit['end_time'])&&$edit['end_time']?substr($edit['end_time'],0,5):'17:00')?>"></div><div class="full"><label>Trabajo previsto</label><input name="title" value="<?=se($edit['title']??'Instalación / trabajo en obra')?>" required></div><div><label>Estado</label><select name="status"><option value="planificado" <?=($edit['status']??'planificado')==='planificado'?'selected':''?>>Planificado</option><option value="realizado" <?=($edit['status']??'')==='realizado'?'selected':''?>>Realizado</option><option value="cancelado" <?=($edit['status']??'')==='cancelado'?'selected':''?>>Cancelado</option></select></div><div class="full"><label>Técnicos asignados</label><div class="checks"><?php foreach($techUsers as $u):?><label class="check"><input type="checkbox" name="users[]" value="<?=$u['id']?>" <?=in_array((int)$u['id'],$editUsers,true)?'checked':''?>> <?=se($u['name'])?></label><?php endforeach;?></div></div><div class="full"><label>Notas / instrucciones</label><textarea name="notes" rows="4"><?=se($edit['notes']??'')?></textarea></div></div><p><button class="btn" type="submit">Guardar planificación</button><?php if($edit):?> <a class="btn light" href="?a=technical_schedule&month=<?=$month?>">Cancelar edición</a><?php endif;?></p></form></section><?php endif;?></main></body></html>